mapper.select:
SELECT cf.* FROM custom_favorite cf
INNER JOIN custom_question cq ON cf.question_id = cq.id
WHERE cf.user_id = #{userId}
  AND cq.is_deleted = 0

  AND cq.category_id = #{categoryId}

ORDER BY cf.create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM custom_favorite cf
INNER JOIN custom_question cq ON cf.question_id = cq.id
WHERE cf.user_id = #{userId}
  AND cq.is_deleted = 0

  AND cq.category_id = #{categoryId}
